// readable — so the packs collapse to a count and only the engine keeps its versions.
export function updatePullText(terminal, { engine, packs }) {
  const engineMoved = engine?.from !== engine?.to;
  const movedPacks = (packs?.plan ?? []).filter((p) => p.from !== p.to);
  const moved = [
    ...(engineMoved ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
    ...movedPacks.map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
  ];
  const summary = [
    ...(engineMoved ? [`engine ${engine?.from == null ? 'unstamped' : `v${engine.from}`} → v${engine?.to}`] : []),
    ...(movedPacks.length ? [`${movedPacks.length} pack${movedPacks.length === 1 ? '' : 's'} upgraded`] : []),
  ];
  const title = summary.length ? `Claudinite update: ${summary.join(' and ')}` : 'Claudinite update';
  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
  if (terminal.action === 'needs-human') {
    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
  } else if (terminal.action === 'apply-stage') {
    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content and runs its tests over what this converge wrote, before anything merges.');
  }
  return { title, body: `${lines.join('\n')}\n` };
}

// --- I/O shell (validated by the live pilot, not unit tests) ----------------

export async function main() {
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
  const token = process.env.GITHUB_TOKEN;
  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
  // report, and restore the working tree — no branch, no commit, no PR, and above
  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
  // which is exactly what the next converge's anti-rewind guard refuses: a rehearsal
  // that wedges its own canary.
  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }

  // Either settings-file name, in the rename's read order: this worker is VENDORED,
  // so the copy running on a member may predate the record that renamed its own
  // file — and one that only knew the new name would report "nothing to update" on
  // every repo still carrying the old one.
  const settingsFile = settingsPath(root);
  if (!existsSync(settingsFile)) { console.log(`update: no ${SETTINGS_FILE} — nothing to update`); return; }
  const declaration = JSON.parse(readFileSync(settingsFile, 'utf8'));

  // One override, one direction: a repo that asked for review gets its PR opened and
  // left; every other repo — the normal shape, the key absent — has it landed.
  const delivery = deliveryFor(declaration);

  // THE TARGET. Which branch this run pushes to, and which pull request it delivers
  // on, is the executor's decision: the task declares
  // `amend_existing_or_create_new_pr`, the executor resolved it before this
  // subprocess started — this cycle's own branch where the last one's pull request
  // is gone or conflicted, that pull request's own branch otherwise — and handed
  // both in. Nothing here reads the open pull requests or picks a name.
  //

// canary world rule — the vendored mount is present and carries the engine's
// world-sweep entry point.
//
// This is a LIVENESS PROBE, not an opinion. If the pack loader ever stops
// discovering local packs, this rule stops running and the canary's world sweep
// goes quiet rather than red — so the rule is paired with the selftest, which
// asserts the rule was dispatched at all. What this rule itself catches is the
// other half: a converge that lands a declaration without the tree it declares.
//
// It can only fire when the mount is missing, and when the mount is missing the
// sweep could not have started from it — so in normal operation it never fires.
// That is the point: a canary rule that has opinions makes the canary red for
// reasons unrelated to the canon ref under test.
//
// Local-pack check modules are dependency-free on purpose: plain finding
// objects, no imports out of `.claudinite/shared/` — committed consumer code
// must not reach into the vendored canon (the `claudinite-isolation` rule
// enforces this), because that tree is refreshed nightly and refactored
// upstream.
const id = 'canary/mount-present';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the canary only means something while it is a real member — without the vendored mount ' +
  'a rehearsal against a canon ref proves nothing about consumers';

const ENTRY = '.claudinite/shared/engine/checks/check_the_world.mjs';

export default {
  id,
  severity,
  description: 'the vendored Claudinite mount is present at .claudinite/shared/',
  doc,
  why,

  run(ctx) {
    if (ctx.exists(ENTRY)) return [];
    return [{
      rule: id,
      severity,
      file: ENTRY,
      line: null,
      what: `${ENTRY} is missing — the vendored mount is absent or incomplete`,
      why,
      fix: 'run the canon\'s vendoring/apply-vendor-set.mjs against this repo to rebuild .claudinite/shared/',
      doc,
    }];
  },
};

// canary work rule — a session that edits the canary pack must leave it loadable.
//
// Work scope, so it judges the change in front of the session (the Stop hook),
// not the repo at rest: it only looks when the branch actually touched the pack
// directory. A session that never goes near it is never asked about it.
//
// Like its world-scope sibling this is a liveness probe with a real edge case
// attached — deleting `pack.mjs` or `RULES.md` while keeping the `local/canary`
// declaration turns every later session into a blocking `config` error at load,
// which is the least debuggable way for this repo to break. In normal operation
// it never fires; its job is to prove work-scope dispatch reached a local pack.
//
// Dependency-free by the same rule as the world-scope module: plain finding
// objects, no imports out of `.claudinite/shared/`.
const id = 'canary/pack-intact';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the declaration names local/canary — if the manifest or its prose goes missing the pack ' +
  'loader raises a blocking config error on every later session, in this repo and in every rehearsal of it';

const DIR = '.claudinite/local/packs/canary/';
const REQUIRED = [`${DIR}pack.mjs`, `${DIR}RULES.md`];

export default {
  id,
  severity,
  description: 'a change touching the canary pack leaves its manifest and prose in place',
  doc,
  why,
  scope: 'work',

  run(work) {
    if (!work.changedFiles.some((f) => f.startsWith(DIR))) return [];
    return REQUIRED.filter((f) => !work.exists(f)).map((file) => ({
      rule: id,
      severity,
      file,
      line: null,
      what: `${file} is gone, but .claudinite-checks.json still declares local/canary`,
      why,
      fix: `restore ${file}, or drop "local/canary" from the "packs" list in .claudinite-checks.json`,
      doc,
    }));
  },
};

